from azure.cosmos import CosmosClient

def conditional_update(id, payload, config=None):
    config = config or {}
    with CosmosClient(config['endpoint'], credential=config['api_key']) as client:
        container = client.get_database_client(config['database']).get_container_client(config['container'])
        document = container.read_item(item=id, partition_key=id)
        for key, value in payload.items():
            if key in document:
                document[key] = value
        container.upsert_item(document)
    return document

from azure.cosmos import CosmosClient

def get_client(config):
    return CosmosClient(config['endpoint'], credential=config['api_key'])

def get_container(client, database, container):
    return client.get_database_client(database).get_container_client(container)

def normalize_payload(payload):
    return {k: v for k, v in payload.items() if v is not None}

def normalize_response(response):
    return {k: v for k, v in response.items() if v is not None}

def summarize_records(records):
    summary = {}
    for record in records:
        for key, value in record.items():
            if key not in summary:
                summary[key] = []
            summary[key].append(value)
    return summary

import re

def check_unsafe_content(fields):
    unsafe_patterns = [r'<script>', r'<img', r'<a']
    for field in fields:
        if any(re.search(pattern, field) for pattern in unsafe_patterns):
            return True
    return False

from google.cloud import translate_v2 as translate

def translate_fields(fields, target_language):
    client = translate.Client()
    translated_fields = {}
    for key, value in fields.items():
        translated_fields[key] = client.translate(value, target_language=target_language)['translatedText']
    return translated_fields
